<?php
namespace App\Services;
use App\Enums\ShipmentStatus; use App\Models\Customer; use App\Models\Shipment; use Illuminate\Support\Facades\DB;
class ShipmentService {public function __construct(private TrackingNumberService $trackingNumbers){} public function create(Customer $customer,string $origin,string $destination,?string $currentLocation=null,$estimatedDelivery=null,?int $createdBy=null):Shipment{return DB::transaction(function()use($customer,$origin,$destination,$currentLocation,$estimatedDelivery,$createdBy){$shipment=Shipment::create(['customer_id'=>$customer->id,'tracking_number'=>$this->trackingNumbers->generate(),'origin'=>$origin,'destination'=>$destination,'current_location'=>$currentLocation??$origin,'status'=>ShipmentStatus::PENDING,'estimated_delivery'=>$estimatedDelivery]);$shipment->events()->create(['status'=>ShipmentStatus::PENDING,'location'=>$currentLocation??$origin,'description'=>'Shipment created.','created_by'=>$createdBy]);return $shipment->load('customer','events');});}}
